using System;
using System.Text.Json.Serialization;
using WalmartApIs.Core.Enum;

namespace WalmartApIs.Models.Enums;

/// <summary>
/// | Attribute | Description | Data Type
/// | --- | ----------- | -------
/// | title | Product Title | string |
/// | sku | An arbitrary alphanumeric unique ID, seller-specified, identifying each item | string |
/// | itemId | Specifies the item identifier generated by Walmart | string |
/// </summary>
[JsonConverter(typeof(StringEnumConverter<Field11>))]
public sealed record Field11 : OpenStringEnum<Field11>
{
    private Field11(string value) : base(value)
    {
    }

    public static readonly Field11 Title = new("title");

    public static readonly Field11 Sku = new("sku");

    public static readonly Field11 ItemId = new("itemId");

    public TResult Match<TResult>(Func<TResult> onTitle,
        Func<TResult> onSku,
        Func<TResult> onItemId,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == Title => onTitle(),
            _ when this == Sku => onSku(),
            _ when this == ItemId => onItemId(),
            _ => otherwise(Value)
        };

    public void Match(Action onTitle, Action onSku, Action onItemId, Action<string> otherwise)
    {
        if (this == Title) onTitle();
        else if (this == Sku) onSku();
        else if (this == ItemId) onItemId();
        else otherwise(Value);
    }
}
